package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class ThermalPulseReceiverBlock extends PassiveDirectionalSignalBlock{public ThermalPulseReceiverBlock(Properties p){super(p);}@Override public MapCodec<ThermalPulseReceiverBlock> codec(){return RedstoneEngineering.THERMAL_PULSE_RECEIVER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.min(15,InformationRuntime.value(l,"thermal_pulse",p));}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,8);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int v=InformationRuntime.value(l,"thermal_pulse",p);if(v>0)InformationRuntime.write(l,"thermal_pulse",p,Math.max(0,v-1),InformationRuntime.aux(l,"thermal_pulse",p),v>1,Math.max(0,InformationRuntime.quality(l,"thermal_pulse",p)-5));updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,8);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Thermal pulse receiver="+outputValue(l,p,s)+"/15 | deliberately low bandwidth"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}